/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn arm64_dtb(core: coretypes.Arm64CoreType) ?i32 {
    return switch (core) {
        .armv8, .cortexa53, .cortexa57, .cortexa72, .cortexa73, .falkor, .thunderx, .thunderx2t99, .tsv110, .emag8180, .neoversen1, .neoversev1, .neoversev2, .neoversen2, .thunderx3t110, .cortexa55, .armv8sve, .a64fx, .armv9sme, .vortex, .vortexm4, .cortexa76, .cortexa510, .cortexa710, .cortexx1, .cortexx2, .ampere1, .ft2000 => 64,
        .unknown => null,
    };
}
